/**
 *
 * DataTableLoading is a component that displays a loading overlay inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableLoading
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableLoading component.
 */
export type DataTableLoadingPassThroughType<E> = PassThroughType<DataTableLoadingInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableLoading component.
 */
export interface DataTableLoadingPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableLoadingPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataTableLoading component.
 */
export interface DataTableLoadingProps extends BaseComponentProps<DataTableLoadingInstance, unknown, DataTableLoadingPassThrough> {
}
/**
 * Defines valid state in DataTableLoading component.
 */
export interface DataTableLoadingState {
}
/**
 * Defines the methods and properties exposed by DataTableLoading component.
 */
export interface DataTableLoadingExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableLoading component.
 */
export type DataTableLoadingInstance = ComponentInstance<DataTableLoadingProps, DataTableLoadingState, DataTableLoadingExposes>;
